"""Pending binary printf and scanner mechanisms, final vsprintf.c regions."""
def register(topic,q,detail):
    def lesson(title,symbol,why,principle,use,reading,qa,cards):
        topic(title,'관찰·디버깅','lib/vsprintf.c',symbol,why,principle,use,reading,
              *(q(*x) for x in qa),details=[detail(*x) for x in cards])
    lesson('Binary Printf·Word 용량과 인자 Packing','vbin_printf',
      'Format 문자열과 인자 자료를 나누어 저장할 때 문자열 출력과 다른 용량 단위 및 정렬을 이해합니다.',
      'CONFIG_BINARY_PRINTF의 vbin_printf는 format_decode로 인자를 분류하고 일반 문자는 저장하지 않습니다. save_arg는 8byte 타입을 4byte 정렬 뒤 두 u32로 저장하고 작은 타입은 해당 sizeof 정렬을 사용합니다. 저장 공간이 부족해도 logical str는 인자 크기만큼 이동합니다. 마지막에는 str를 u32 경계로 올린 뒤 bin_buf와의 차이를 word 수로 반환합니다. bprintf는 가변 인자를 이 함수에 연결합니다.',
      'Size를 byte나 문자 대신 u32 word 개수로 제공합니다. Format과 충분한 binary buffer를 함께 유지합니다. 이 자료는 native 타입 폭과 endian을 사용하는 내부 표현이며 플랫폼 독립 파일 저장 형식으로 가정하지 않습니다.',
      'save_arg의 8byte 특별 경로, PTR_ALIGN, 마지막 word 차이를 읽으세요.',
      [('size=4는 이 함수에서 저장공간 몇 byte를 뜻하는가?', 'u32 네 개의 16byte이다','문자 네 개의 4byte이다','bin_buf+size는 u32 pointer 연산입니다. Text formatter의 size 단위와 다릅니다.'),
       ('64bit 인자는 8byte alignment로만 저장하는가?', '이 경로는 u32 크기 4byte 정렬을 사용한다','항상 8byte 정렬만 허용한다','원본은 8byte 값을 두 u32 조각으로 처리합니다. PTR_ALIGN의 인자는 sizeof(u32)입니다.')],
      [('원래 형식은 별도','Literal text와 percent는 binary 인자 buffer에 저장하지 않습니다. 나중 bstr_printf가 같은 format을 읽으므로 format 변경은 인자 해석을 바꿀 수 있습니다.'),
       ('작은 타입','char·short 인자도 가변 호출에서는 int로 읽고 저장 크기에 맞춰 cast합니다. Text engine의 int 승격 처리와 연결하되 binary 저장 폭은 다릅니다.')])
    lesson('Binary Pointer·즉시 Dereference와 지연 표시','vbin_printf',
      '로그 자료를 나중에 표시할 때 원래 객체를 다시 읽을지 당시 문자열을 저장할지 선택하는 원리를 배웁니다.',
      'S·s·x·K·e와 alphanumeric suffix 없는 pointer는 raw pointer 인자를 저장합니다. 그 외 pointer 확장은 저장 시점에 pointer formatter를 호출하고 표시 문자열을 NUL과 함께 남깁니다. Object dereference가 필요한 자료를 나중까지 살아 있게 가정하지 않으려는 선택입니다. Strings도 strlen+1 크기의 내용을 inline 저장합니다.',
      'Format 선택에 따라 snapshot 내용인지 나중 표시할 pointer 값인지 구분합니다. 지연 주소 표시는 hash·권한 정책이 나중에 적용될 수 있습니다. Binary buffer를 임의 format으로 재해석하지 않습니다.',
      '지연 pointer 목록, generic preformat, inline string과 suffix skip을 읽으세요.',
      [('MAC 주소 확장 같은 generic pointer는 언제 object를 읽는가?', 'binary 저장 시점에 문자열로 만든다','항상 나중 bstr_printf가 원래 object를 읽는다','선택한 raw pointer 목록 밖의 확장은 즉시 formatter를 호출합니다. 당시 표시 자료를 저장합니다.'),
       ('x suffix의 pointer는?', '주소 값을 binary 인자로 저장한다','항상 문자열 snapshot으로 저장한다','x는 raw pointer 저장 목록에 있습니다. 나중 formatter가 그 값을 읽어 표시합니다.')],
      [('주소 재사용과 수명','값을 저장하는 것과 객체 수명을 보장하는 것은 다릅니다. Raw pointer 표시 경로에서 실제 객체를 역참조하는지, symbol 조회인지 각 destination 계약을 확인합니다.'),
       ('별표 인자','WIDTH/PRECISION도 int 인자로 저장합니다. Pointer를 즉시 표시할 때 필요한 width를 spec에 반영하는 특별 처리와 나중 text decode의 재개 처리를 구분합니다.')])
    lesson('Binary Buffer 경계·원본 분기의 실제 한계','vbin_printf',
      '원본 주석의 반환 계약과 실제 저장 조건이 어긋나는 경계를 읽고 호출 전제를 구체적으로 확인합니다.',
      '문자열 복사는 str+len<end라는 엄격한 조건을 쓰므로 len이 남은 공간과 정확히 같으면 복사하지 않습니다. Generic pointer 표시 뒤에는 str+1<end가 아니면 end[-1]에 NUL을 씁니다. Size 0에서도 이 branch에 들어가면 지정된 범위 앞의 저장이 발생할 수 있습니다. 반환 word 수만으로 모든 내용이 유효하게 저장됐다고 판단할 수 없는 경계가 있습니다.',
      '이 고정 버전의 binary API에 충분한 여유 공간과 유효 인자를 제공합니다. 크기 0 pointer preformat을 일반 text 길이 계산처럼 사용하지 않습니다. 학습 시험은 실제 배열 안의 guard로 관찰하며 사용자 자료나 운영 커널을 손상시키지 않습니다.',
      'String의 <와 <= 차이, pointer의 end[-1], 반환 word 정렬을 읽으세요.',
      [('NUL 포함 문자열 길이가 남은 byte와 정확히 같으면?', '이 원본 branch는 복사하지 않는다','언제나 정확히 맞춰 복사한다','조건은 str+len<end입니다. 일반 memcpy 크기 검사의 <= 계약과 다르게 동작합니다.'),
       ('Generic pointer의 size0 호출을 안전한 길이 계산으로 취급해도 되는가?', 'end[-1] branch가 있어 그렇게 가정하지 않는다','모든 branch가 쓰기를 완전히 생략한다','이 분기는 size0을 별도로 막지 않습니다. 지정 범위 밖 쓰기의 실제 위치를 source와 guard 시험으로 확인합니다.')],
      [('문서와 구현','주석의 반환<=size 조건만 믿기 전에 string·pointer 분기의 실제 조건을 함께 봅니다. 문제 풀이도 이 고정 commit의 동작을 기준으로 합니다.'),
       ('검증 방식','일부러 invalid pointer를 실행하지 않고 큰 실제 배열 내부에서 logical buffer 범위를 줄여 guard 변화를 관찰합니다. Memory 접근은 시험 배열 안에 두고 API 범위 위반만 확인합니다.')])
    lesson('Bstr Printf·Binary 인자의 정렬과 재생','bstr_printf',
      'Binary 인자 자료에서 숫자와 문자열을 다시 출력할 때 저장한 표현과 같은 해석 규칙이 필요함을 배웁니다.',
      'get_arg는 타입 크기에 맞춰 args를 정렬하고 8byte 값은 두 u32로 복원합니다. Strings는 inline NUL 문자열 뒤로 args를 옮깁니다. 지연 pointer 목록은 get_arg(void*) 뒤 pointer로 표시하고 미리 만든 generic pointer는 저장 문자열을 복사합니다. Numeric·width·precision은 decode 결과에 맞춰 읽습니다. 마지막에는 text 출력의 NUL과 logical 길이 반환을 처리합니다.',
      '동일 format으로 만든 충분한 유효 bin_buf를 전달합니다. 이 함수에는 binary 입력 길이 인자가 없어 임의 외부 자료를 안전하게 검사하는 decoder가 아닙니다. 저장 당시의 타입 폭·endian·alignment와 재생 환경을 맞춥니다.',
      'get_arg, inline strlen 소비, process pointer 선택, 최종 NUL을 읽으세요.',
      [('임의로 잘린 binary 자료를 안전하게 거부할 길이 인자가 있는가?', '이 함수에는 bin_buf 입력 길이가 없다','size가 binary 입력 길이를 뜻한다','size는 목적 text buffer의 용량입니다. Caller가 유효한 binary 자료를 제공해야 합니다.'),
       ('숫자의 format을 저장 후 바꾸면 자동으로 원래 타입을 복원하는가?', '같은 format과 자료 계약이 필요하다','모든 타입 tag가 buffer에 자동 보존된다','get_arg 타입은 format decoder에서 선택합니다. Buffer 자체가 독립적으로 모든 타입을 설명하지 않습니다.')],
      [('Generic Pointer 잘림','미리 만든 pointer 문자열 branch는 str<end일 때만 len과 args 진행을 계산합니다. 출력이 이미 가득 찬 경우 logical 길이와 다음 인자 해석이 일반 vsnprintf와 달라질 수 있는 원본 한계입니다.'),
       ('N Format 차이','vbin_printf 주석은 n 무시를 언급하지만 공통 format_decode는 n을 INVALID로 만듭니다. 실제 저장·재생은 INVALID에서 멈춥니다. 주석만으로 계속 인자를 읽는다고 설명하지 않습니다.')])
    lesson('Vsscanf 흐름·공백 Literal과 대입 개수','vsscanf',
      '출력과 반대 방향으로 text를 읽을 때 소비한 문자 수와 성공적으로 저장한 항목 수의 차이를 배웁니다.',
      'Format의 whitespace는 skip_spaces로 입력의 임의 개수 공백과 대응하며 일반 문자는 정확히 비교합니다. Conversion을 처리한 뒤 num을 성공 대입 개수로 증가시킵니다. n은 현재 str-buf를 int pointer에 저장하지만 num은 늘리지 않습니다. Percent literal도 대입 개수에 포함하지 않습니다. 모르는 format이나 불일치에서 지금까지의 num을 반환합니다. Sscanf는 va_list 연결 wrapper입니다.',
      'Format에 맞는 실제 목적 pointer 타입과 저장공간을 제공합니다. 반환을 읽은 byte 수로 사용하지 않고 필요한 대입 개수와 비교합니다. 출력 formatter가 n을 금지한다고 입력 scanner도 같은 계약이라고 가정하지 않습니다.',
      '공백 처리, literal 비교, num++, n의 별도 continue를 읽으세요.',
      [('숫자 하나를 읽고 n에 소비 길이를 저장하면 대입 count는?', '숫자 대입의 1이다','n을 포함해 언제나 2이다','n은 num을 증가시키지 않습니다. 읽은 문자 수는 지정한 int 객체에 별도로 저장합니다.'),
       ('Format의 공백 한 칸은 입력 공백 정확히 한 칸만 요구하는가?', '0개 이상의 whitespace와 대응한다','언제나 한 space byte만 요구한다','원본 주석과 skip_spaces 흐름은 임의 양의 공백뿐 아니라 없는 경우도 허용합니다.')],
      [('출력과 입력','vsnprintf의 n은 INVALID이지만 vsscanf의 n은 지원합니다. 이름이 printf/scanf 계열이라고 같은 format 지원 목록이라고 생각하지 않습니다.'),
       ('실패 결과','EOF sentinel을 반환하는 일반 libc 계약과 달리 이 원본은 num을 반환합니다. 부분 성공과 0 성공의 의미를 caller가 명시적으로 확인합니다.')])
    lesson('Scanner Char·String과 저장공간 제한','vsscanf',
      '문자 배열로 입력을 저장할 때 NUL 종료와 field width의 역할이 conversion마다 다름을 배웁니다.',
      'c는 기본 width 1이고 whitespace를 자동 건너뛰지 않으며 읽은 byte를 그대로 저장해 NUL을 붙이지 않습니다. s는 공백을 먼저 건너뛰고 다음 공백 또는 width까지 복사한 뒤 NUL을 붙입니다. S의 기본 width는 SHRT_MAX입니다. C는 입력이 먼저 끝나면 요청보다 적게 복사해도 num을 늘리는 원본 경로가 있습니다.',
      'S에는 목적 배열 크기보다 1 작은 명시적 width를 제공하고 C에는 필요한 byte 공간을 확보합니다. Scanner가 배열 크기를 자동 알아낸다고 생각하지 않습니다. Partial c와 공백 뒤 empty s의 실제 분기를 source로 확인합니다.',
      'c do loop, s leading-space와 마지막 NUL, 기본 폭을 읽으세요.',
      [('c conversion이 한 byte를 복사한 뒤 자동 NUL을 넣는가?', 'NUL을 추가하지 않는다','언제나 두 번째 byte에 NUL을 넣는다','C는 raw 문자 저장입니다. 문자열 종료가 필요한 caller는 별도 공간과 처리를 준비합니다.'),
       ('8byte 목적 배열에 s를 저장할 때 안전하게 제공할 width는?', '최대 7이다','기본 SHRT_MAX를 그대로 사용한다','문자 7개와 종료 NUL 한 개가 필요합니다. 실제 배열 크기는 scanner에 전달되지 않습니다.')],
      [('공백만 남은 S','초기 *str 검사 뒤 skip_spaces로 끝에 도달하면 복사 0개와 NUL 저장 후 num을 늘릴 수 있습니다. 일반 libc의 일치 실패 처리와 같다고 가정하지 않습니다.'),
       ('Field Width 타입','이 scanner의 field_width는 s16입니다. Literal 숫자를 읽어 대입한 뒤 <=0이면 멈춥니다. 매우 큰 폭을 충분한 배열 크기라는 이유만으로 전달하지 않습니다.')])
    lesson('Scanner 집합·256bit Bitmap과 Negate','vsscanf',
      '문자 집합 입력을 bitmap으로 바꾸어 byte membership을 빠르게 확인하는 원리를 배웁니다.',
      'Bracket conversion은 256bit set을 0으로 초기화하고 format 안의 각 byte를 u8 index로 __set_bit합니다. ^이면 complement 뒤 NUL bit를 지웁니다. 시작 문자가 집합에 있어야 하고 width까지 test_bit로 읽은 뒤 NUL을 붙입니다. Width는 필수이고 빈 집합·닫는 bracket 부재는 실패입니다. Range 문법과 닫는 bracket 자체 일치, suppression bracket은 지원하지 않습니다.',
      '명시적 width와 종료 공간을 준비합니다. a-z를 alphabetic range로 생각하지 않고 a,hyphen,z 세 문자 집합으로 읽습니다. u8 index는 0부터 255의 byte 집합이며 Unicode code point 전체 집합이 아닙니다.',
      'DECLARE_BITMAP(256), set/complement/clear0, nonempty match와 width를 읽으세요.',
      [('집합 a-z가 이 구현에서 뜻하는 것은?', 'a와 hyphen과 z 세 문자이다','모든 소문자 alphabet이다','원본은 range를 지원하지 않습니다. 각 format byte를 개별 bit로 등록합니다.'),
       ('Negate 뒤 NUL bit를 지우는 이유는?', '문자열 끝을 입력 자료로 계속 복사하지 않기 위해','출력 NUL을 전부 금지하기 위해','Complement는 NUL bit도 켤 수 있습니다. 입력 종료에 도달하면 membership loop를 끝내야 합니다.')],
      [('작은 Lookup 집합','256개의 가능한 byte를 256bit로 표현합니다. 각 입력 byte의 존재 여부는 해당 bit를 검사하며 문자 목록을 매번 순회하지 않습니다.'),
       ('폭과 종료','복사한 byte 개수 밖에 목적 NUL이 하나 더 필요합니다. 집합 검사가 입력 의미를 제한하지만 목적 배열의 실제 크기를 알아내지는 않습니다.')])
    lesson('Scanner 숫자·진법과 목적 Pointer 타입','vsscanf',
      '숫자 입력의 진법·부호·길이 modifier를 해석하고 올바른 목적 객체에 저장하는 원리를 배웁니다.',
      'o는8,x/X는16,d/u는10,i는자동 진법입니다. d/i만 부호를 선택하고 공백 뒤 시작 숫자를 검사합니다. Minus이면 다음 숫자를 확인하고 width1이면 중단합니다. Simple 길이 제한 helper로 변환한 뒤 hh/h/l/ll/z 및 signed 여부에 맞는 목적 pointer로 대입합니다. Overflow 상태나 목적 타입 범위 초과를 별도 오류 코드로 보고하지 않습니다.',
      'Format에 맞는 signed/unsigned 목적 타입을 제공합니다. Z는 size_t pointer 경로이며 임의 ssize_t 입력 계약이라고 해석하지 않습니다. 엄격한 값 범위 검증이 필요한 입력에는 kstrtox의 명시적 오류 계약을 확인합니다.',
      'digit gate, simple_strntoll/ull, qualifier별 va_arg(pointer)를 읽으세요.',
      [('i로 010을 읽으면 기본 진법은?', '자동 판정으로 octal이다','언제나 decimal이다','i는 base=0이고 simple radix 보정이 앞 0을 octal로 판단합니다.'),
       ('숫자가 목적 unsigned char 범위를 넘으면 ERANGE를 반환하는가?', '이 scanner는 좁은 타입 대입의 별도 범위 오류를 반환하지 않는다','모든 conversion이 ERANGE를 별도로 반환한다','Simple helper 결과를 목적 타입에 대입하고 num을 늘립니다. 엄격한 범위 검사 API와 다릅니다.')],
      [('Plus 시작','실제 digit gate와 simple helper에는 이 scanner에서 plus를 받아들이는 branch가 없습니다. 일반 libc scanf의 문법을 그대로 대입하지 않습니다.'),
       ('출력 Promotion과 입력 Pointer','출력 hh는 int로 승격된 값을 읽지만 입력 hh는 signed/unsigned char pointer를 읽습니다. 값의 승격과 결과 저장 공간 타입은 다른 계약입니다.')])
    lesson('Scanner 별표·공백 단위 Suppression 한계','vsscanf',
      '형식의 별표가 출력 폭 인자와 전혀 다른 역할이며 이 scanner의 구현 범위가 제한됨을 배웁니다.',
      'Scanner에서 *는 결과 대입을 생략하는 branch입니다. 이 원본은 format을 다음 whitespace 또는 %까지, 입력을 다음 whitespace까지 이동합니다. 개별 숫자 conversion만 정밀하게 수행해 버리는 방식이 아닙니다. Bracket suppression을 만나면 지금까지 count로 반환합니다. Input이 끝이면 중단합니다.',
      '고정 버전의 suppression이 whitespace 단위라는 조건으로 사용합니다. %*d 뒤 literal comma 같은 문법을 일반 libc와 동일하게 해석한다고 가정하지 않습니다. 버릴 token의 구분과 다음 conversion의 시작을 실제 흐름으로 확인합니다.',
      '두 while의 서로 다른 종료 조건과 bracket의 조기 반환을 읽으세요.',
      [('입력 12abc 공백 34에서 별표 숫자 branch는 앞 token을 어디까지 넘기는가?', '12abc 전체를 다음 whitespace까지 넘긴다','숫자 12만 정확히 소비한다','이 suppression branch는 숫자 변환 helper를 호출하지 않습니다. Input은 whitespace까지 이동합니다.'),
       ('출력 printf의 *처럼 별도 int 폭 인자를 읽는가?', 'Scanner 별표는 대입 생략 경로이다','항상 int 폭 인자를 추가로 소비한다','출력 파서의 별표와 입력 scanner의 별표 계약은 다릅니다. 이 branch는 목적 va_arg를 읽지 않습니다.')],
      [('문자 구분자 한계','Format에 comma가 포함되어 있어도 suppression의 format loop는 다음 %나 whitespace까지 넘어갑니다. 입력 loop는 comma에서 멈추지 않아 뒤 자료까지 같은 token으로 소비할 수 있습니다.'),
       ('반환 Count','생략한 conversion은 num을 증가시키지 않습니다. 뒤의 실제 대입 결과만 성공 개수에 포함합니다. Unsupported bracket suppression은 전체 parsing을 조기에 끝냅니다.')])
